import { heroName, heroImage } from './heroes.js';

const h = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const available = n => typeof n === 'number' && Number.isFinite(n);
const fmt = n => available(n) ? Math.round(n).toLocaleString('en-US') : '—';
const fixed = n => available(n) ? n.toFixed(2) : '—';
const pct = n => available(n) ? Math.round(n) + '%' : '—';
const numericMean = ns => { const numbers = ns.filter(available); return numbers.length ? numbers.reduce((a,b)=>a+b,0)/numbers.length : null; };
const radiant = p => p.player_slot < 128;
const players = m => Array.isArray(m.players) ? m.players : [];
const account = p => /^\d+$/.test(String(p.account_id)) && +p.account_id > 0 && +p.account_id < 4294967295 ? String(p.account_id) : null;
const ign = p => p.personaname || p.persona_name || p.name || (account(p) ? 'Player ' + account(p) : 'Anonymous');
const hero = p => heroName(p.hero_id) || 'Hero ' + p.hero_id;
const duration = n => available(n) ? (n < 0 ? '−' : '') + Math.floor(Math.abs(n)/60) + ':' + String(Math.floor(Math.abs(n)%60)).padStart(2,'0') : '—';
const titleCase = key => String(key ?? '').replace(/_/g,' ').replace(/\b[a-z]/g,c=>c.toUpperCase());
const teamKills = (m,p) => {
  const score = radiant(p) ? m.radiant_score : m.dire_score;
  if (available(score)) return score;
  const team = players(m).filter(x=>radiant(x)===radiant(p));
  return team.length && team.every(x=>available(x.kills)) ? team.reduce((n,x)=>n+x.kills,0) : null;
};
const kda = p => [p.kills,p.assists,p.deaths].every(available) ? (p.kills+p.assists)/Math.max(1,p.deaths) : null;
const kp = (m,p) => {
  const kills = teamKills(m,p);
  return available(kills) && kills > 0 && available(p.kills) && available(p.assists) ? Math.min(100,100*(p.kills+p.assists)/kills) : null;
};
function matchMvp(m) {
  return players(m).filter(p=>typeof m.radiant_win==='boolean' && radiant(p)===m.radiant_win && available(kda(p)))
    .sort((a,b)=> ((kda(b)+(kp(m,b) || 0)/10) - (kda(a)+(kp(m,a) || 0)/10)) || a.player_slot-b.player_slot)[0];
}
function closeScore(m) {
  const lead = Array.isArray(m.radiant_gold_adv) ? m.radiant_gold_adv.filter(available) : [];
  if (lead.length>=2) return lead.filter(v=>Math.abs(v)<=3000).length/lead.length;
  const a=m.radiant_score,b=m.dire_score;
  return available(a) && available(b) && a+b ? 1-Math.abs(a-b)/(a+b) : -1;
}
function aggregate(id,name,rows){
  const p = rows.map(r=>r.p);
  const sum = key => p.every(v=>available(v[key])) ? p.reduce((n,v)=>n+v[key],0) : null;
  const [kills,deaths,assists] = ['kills','deaths','assists'].map(sum);
  const outcomes = rows.filter(r=>typeof r.m.radiant_win === 'boolean');
  const wins = outcomes.filter(r=>radiant(r.p) === r.m.radiant_win).length;
  const losses = outcomes.length-wins;
  const picks = new Map();
  for(const row of p) picks.set(row.hero_id,(picks.get(row.hero_id)||0)+1);
  const heroId = [...picks].sort((a,b)=>b[1]-a[1] || a[0]-b[0])[0]?.[0];
  return {id,name,games:p.length,wins,losses,winRate:outcomes.length?wins/outcomes.length*100:null,loseRate:outcomes.length?losses/outcomes.length*100:null,kda:kda({kills,deaths,assists}),kills,deaths,assists,
    mvps:rows.filter(r=>r.mvp===r.p).length,gpm:numericMean(p.map(v=>v.gold_per_min)),xpm:numericMean(p.map(v=>v.xp_per_min)),kp:numericMean(rows.map(r=>kp(r.m,r.p))),heroId,rows};
}
export function summary(input) {
  const matches=[...input].sort((a,b)=>(b.start_time||0)-(a.start_time||0)||Number(b.match_id)-Number(a.match_id));
  const pRows=new Map(), hRows=new Map(), rows=[];
  const push=(map,id,row)=>{if(!map.has(id)) map.set(id,[]); map.get(id).push(row);};
  for(const m of matches) {
    const mvp=matchMvp(m);
    for(const p of players(m)) {
      const row={m,p,mvp}; rows.push(row);
      if (account(p)) push(pRows,account(p),row);
      if (+p.hero_id>0) push(hRows,p.hero_id,row);
    }
  }
  const ranked=[...pRows].map(([id,rs])=>aggregate(id,ign(rs.find(r=>r.p.personaname||r.p.name)?.p || rs[0].p),rs)).sort((a,b)=>b.mvps-a.mvps || (b.kda??-1)-(a.kda??-1) || b.games-a.games || a.name.localeCompare(b.name));
  const heroes=[...hRows].map(([id,rs])=>aggregate(id,hero(rs[0].p),rs)).sort((a,b)=>b.games-a.games || b.wins-a.wins || a.name.localeCompare(b.name));
  const awards=[['Bloodthirsty','Kills','kills'],['The enabler','Assists','assists'],['The nuker','Hero damage','hero_damage'],['Money printer','GPM','gold_per_min'],['The demolisher','Tower damage','tower_damage']].flatMap(([title,label,key])=>{
    const r=rows.reduce((best,r)=> available(r.p[key])&&(!best||r.p[key]>best.p[key])?r:best,null);
    return r ? [{title,label,value:r.p[key],name:ign(r.p),heroId:r.p.hero_id,matchId:r.m.match_id}] : [];
  });
  // A replay timeline is stronger evidence than the final scoreboard.
  const parsed = matches.filter(m=>Array.isArray(m.radiant_gold_adv)&&m.radiant_gold_adv.filter(available).length>=2);
  const featuredMatch=[...(parsed.length?parsed:matches)].sort((a,b)=>closeScore(b)-closeScore(a))[0]||null;
  return {matches,players:ranked,heroes,featuredMatch,featuredPlayer:ranked[0]||null,awards};
}
function portrait(id) {
  return '<img class="sl-avatar" src="'+h(heroImage(id))+'" alt="" loading="lazy">';
}
function playerName(p) {
  return account(p) ? '<a href="#player/'+account(p)+'">'+h(ign(p))+'</a>' : h(ign(p));
}
function table(headers,body) {
  return '<div class="sl-scroll"><table class="sl-table"><thead><tr>'+headers.map(s=>'<th scope="col">'+s+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table></div>';
}
function section(label,body) {
  return '<section class="sl-section"><h2>'+label+'</h2>'+body+'</section>';
}
function cells(...xs) {return '<tr>'+xs.map(x=>'<td>'+x+'</td>').join('')+'</tr>';}
export function graph(m) {
  const gold=Array.isArray(m.radiant_gold_adv)?m.radiant_gold_adv:[],xp=Array.isArray(m.radiant_xp_adv)?m.radiant_xp_adv:[];
  if (![gold,xp].some(series=>series.filter(available).length>=2)) return '<p class="sl-empty">Gold and XP timelines are unavailable for this match.</p>';
  const n=Math.max(gold.length,xp.length), limit=Math.max(1000,...[...gold,...xp].filter(available).map(Math.abs));
  const x=i=>52+648*i/(n-1),y=v=>80-v*54/limit;
  const line=(series,colour,dash)=>{let started=false; const d=series.map((v,i)=>{if(!available(v)){started=false;return '';}const cmd=started?'L':'M';started=true;return cmd+x(i).toFixed(2)+' '+y(v).toFixed(2);}).join(' ');return '<path d="'+d+'" fill="none" stroke="'+colour+'" stroke-width="2.5" '+dash+' vector-effect="non-scaling-stroke"/>';};
  const chart='<svg class="sl-graph" role="img" aria-label="Radiant gold and experience advantage over time. Negative values favour Dire." viewBox="0 0 720 170"><g stroke="currentColor" opacity=".15"><path d="M52 26H700 M52 80H700 M52 134H700" stroke-dasharray="4 5"/></g><g fill="currentColor" font-size="12" font-family="sans-serif"><text x="0" y="29">+'+fmt(limit)+'</text><text x="23" y="84">0</text><text x="0" y="138">−'+fmt(limit)+'</text><text x="52" y="161">0m</text><text x="700" y="161" text-anchor="end">'+(n-1)+'m</text></g>'+line(gold,'#e4b365','')+line(xp,'#81b7fb','stroke-dasharray="6 4"')+'</svg>';
  return '<div class="sl-chart"><div class="sl-legend">'+(gold.filter(available).length>=2?'<span>Gold lead</span>':'')+(xp.filter(available).length>=2?'<span class="sl-xp">XP lead</span>':'')+'</div>'+chart+'</div>';
}
export function heroTable(matches) {
  const {heroes}=summary(matches);
  return section('Hero statistics',heroes.length?table(['Hero','Picks','W–L','Win rate','KDA','Avg GPM','Avg XPM'],heroes.map(o=>cells('<span class="sl-person">'+portrait(o.id)+h(o.name)+'</span>',o.games,o.wins+'–'+o.losses,pct(o.winRate),fixed(o.kda),fmt(o.gpm),fmt(o.xpm))).join('')):'<p class="sl-empty">Import a match to see hero picks.</p>');
}
export function itemKey(raw) {
  if (raw == null || raw === '' || raw === 0 || raw === '0') return '';
  if (/^\d+$/.test(String(raw))) return ITEM_IDS[raw] || '';
  return String(raw).replace(/^item_/, '');
}
export function item(raw) {
  const key = itemKey(raw);
  return ITEM_NAMES[key] || (key ? titleCase(key) : raw ? 'Item '+String(raw) : 'Empty');
}
export function ability(raw) {
  return ABILITY_NAMES[raw] || (typeof raw==='string' && !/^\d+$/.test(raw) ? titleCase(raw) : 'Ability '+raw);
}
function builds(p){
  const slots=[0,1,2,3,4,5].map(i=>p['item_'+i]),hasInventory=slots.some(available);
  const inv=slots.filter(v=>available(v)&&v>0).map(key=>'<span class="sl-chip">'+h(item(key))+'</span>').join('');
  const purchases=p.purchase_log, upgrades=p.skill_build?.length?p.skill_build:p.ability_upgrades_arr || (Array.isArray(p.ability_upgrades)?p.ability_upgrades.map(a=>a.ability):null);
  const purchasesHTML=Array.isArray(purchases)&&purchases.length?purchases.map(x=>'<span class="sl-chip"><small>'+duration(x.time)+'</small> '+h(item(x.key ?? x.item_id))+'</span>').join(''):'<span class="sl-muted">Purchase timing unavailable.</span>';
  const skills=Array.isArray(upgrades)&&upgrades.length?upgrades.map((upgrade,i)=>{const id=upgrade?.key ?? upgrade; const name=ABILITY_NAMES[id] || (typeof id==='string'?titleCase(id):'Ability '+id);return '<span class="sl-chip"><small>'+h(upgrade?.hero_level ?? i+1)+'</small> '+h(name)+'</span>';}).join(''):'<span class="sl-muted">Skill order unavailable.</span>';
  return '<details class="sl-build"><summary>'+portrait(p.hero_id)+'<strong>'+h(ign(p))+'</strong> <span>'+h(hero(p))+'</span></summary><div><h4>Final inventory</h4>'+(inv || (hasInventory?'Empty inventory':'Inventory unavailable.'))+'<h4>Purchase timeline</h4>'+purchasesHTML+'<h4>Ability upgrade order</h4>'+skills+'</div></details>';
}
export function matchView(m) {
  if (!m) return '<p class="sl-empty">Match unavailable.</p>';
  const mvp=matchMvp(m),outcome=typeof m.radiant_win==='boolean'?(m.radiant_win?'Radiant victory':'Dire victory'):'Result unavailable';
  const teams=[true,false].map(isRad=>{
    const team=players(m).filter(p=>radiant(p)===isRad).sort((a,b)=>a.player_slot-b.player_slot);
    const rows=team.map(p=>cells('<span class="sl-person">'+portrait(p.hero_id)+'<span>'+playerName(p)+'<small>'+h(hero(p))+'</small></span></span>',fmt(p.kills)+' / '+fmt(p.deaths)+' / '+fmt(p.assists),pct(kp(m,p)),fmt(p.gold_per_min),fmt(p.xp_per_min),fmt(p.net_worth),fmt(p.hero_damage))).join('');
    return '<h3 class="sl-team '+(isRad?'radiant':'dire')+'">'+(isRad?'Radiant':'Dire')+'</h3>'+table(['Player / Hero','K / D / A','KP','GPM','XPM','Net worth','Hero damage'],rows);
  }).join('');
  return '<article class="sl-detail"><div class="sl-matchhead"><div><small>Match #'+h(m.match_id)+'</small><h2>'+outcome+'</h2></div><strong>'+fmt(m.radiant_score)+' <i>:</i> '+fmt(m.dire_score)+'</strong><span>'+duration(m.duration)+'</span></div>'+section('Team advantage',graph(m))+section('Scoreboard',teams)+(mvp?'<p class="sl-mvp"><b>Tracker MVP</b> '+playerName(mvp)+' · '+h(hero(mvp))+' · '+fixed(kda(mvp))+' KDA · '+pct(kp(m,mvp))+' kill participation.</p>':'')+section('Item and skill builds',players(m).map(builds).join(''))+'</article>';
}
function profile(o) {
  const heroes=new Map();
  for(const r of o.rows){const key=r.p.hero_id;if(!heroes.has(key))heroes.set(key,[]);heroes.get(key).push(r);}
  const hrows=[...heroes].map(([id,rs])=>aggregate(id,hero(rs[0].p),rs)).sort((a,b)=>b.games-a.games).map(a=>cells('<span class="sl-person">'+portrait(a.id)+h(a.name)+'</span>',a.games,pct(a.winRate),fixed(a.kda))).join('');
  const recent=o.rows.map(({m,p,mvp})=>cells('<a href="#match/'+h(encodeURIComponent(m.match_id))+'">#'+h(m.match_id)+'</a>',h(hero(p)),typeof m.radiant_win==='boolean'?(radiant(p)===m.radiant_win?'Win':'Loss'):'—',fmt(p.kills)+' / '+fmt(p.deaths)+' / '+fmt(p.assists),mvp===p?'MVP':'—')).join('');
  return '<article class="sl-detail"><div class="sl-matchhead"><div><small>Player profile</small><h2>'+h(o.name)+'</h2></div>'+portrait(o.heroId)+'</div><div class="sl-kpis">'+[['Matches',o.games],['Wins / losses',o.wins+' / '+o.losses],['Win rate',pct(o.winRate)],['Loss rate',pct(o.loseRate)],['W/L ratio',o.losses?fixed(o.wins/o.losses):o.wins?'Undefeated':'—'],['Overall KDA',fixed(o.kda)],['Match MVPs',o.mvps],['Avg KP',pct(o.kp)],['Avg GPM',fmt(o.gpm)],['Avg XPM',fmt(o.xpm)]].map(([key,v])=>'<div><small>'+key+'</small><strong>'+v+'</strong></div>').join('')+'</div>'+section('Hero pool',table(['Hero','Picks','Win rate','KDA'],hrows))+section('Match history',table(['Match','Hero','Result','K / D / A','Award'],recent))+'</article>';
}
export function playersView(matches,id) {
  const {players:ranked,awards}=summary(matches);
  if(id) {const o=ranked.find(a=>String(a.id)===String(id));return o?profile(o):'<p class="sl-empty">This player has no tracked matches.</p>';}
  const standings=ranked.map((o,i)=>cells(i+1,'<span class="sl-person">'+portrait(o.heroId)+'<a href="#player/'+h(o.id)+'">'+h(o.name)+'</a></span>',o.games,o.wins+'–'+o.losses,pct(o.winRate),fmt(o.kills)+' / '+fmt(o.deaths)+' / '+fmt(o.assists),fixed(o.kda),pct(o.kp),fmt(o.gpm),fmt(o.xpm),o.mvps)).join('');
  const cards=awards.map(a=>'<a class="sl-award" href="#match/'+h(encodeURIComponent(a.matchId))+'"><small>'+h(a.title)+'</small><div>'+portrait(a.heroId)+'<b>'+h(a.name)+'</b></div><strong>'+fmt(a.value)+'</strong> '+h(a.label)+'</a>').join('');
  return section('Player leaderboard',standings?table(['#','Player','Games','W–L','Win rate','Total K / D / A','KDA','Avg KP','Avg GPM','Avg XPM','MVPs'],standings):'<p class="sl-empty">No identified players in the tracked matches.</p>')+'<p class="sl-muted">Ranked by tracker MVPs, then overall KDA. Each match awards MVP to the winning player with the highest KDA + kill participation percentage ÷ 10. Anonymous players appear on match scoreboards.</p>'+(cards?section('Tournament highlights','<div class="sl-awards">'+cards+'</div>'):'');
}
